def plus_pattern(n):
    mid = n // 2                                # the single middle row and column index
    for i in range(n):                          # check every row
        for j in range(n):                       # check every column in that row
            if i == mid or j == mid:
                print("*", end="")                   # this cell is on the middle row or column
            else:
                print(" ", end="")                   # everywhere else stays blank
        print()                                  # move to the next line after the row


if __name__ == "__main__":
    plus_pattern(5)

