import java.util.*;

public class Main {
    void plusPattern(int n) {
        int mid = n / 2;                               // the single middle row and column index
        for (int i = 0; i < n; i++) {                  // check every row
            for (int j = 0; j < n; j++) {                // check every column in that row
                if (i == mid || j == mid) {
                    System.out.print("*");                  // this cell is on the middle row or column
                } else {
                    System.out.print(" ");                  // everywhere else stays blank
                }
            }
            System.out.println();                        // move to the next line after the row
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.plusPattern(5);
    }
}

