import java.util.*;

public class Main {
    void plusPattern(int n) {
        int mid = n / 2;
        String fullRow = "*".repeat(n);                 // the middle row is identical to itself only once
        String sideRow = " ".repeat(mid) + "*" + " ".repeat(n - mid - 1);  // every other row matches this
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(i == mid ? fullRow : sideRow);
            if (i < n - 1) {
                sb.append('\n');
            }
        }
        System.out.println(sb);                        // output the whole pattern with a single call
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.plusPattern(5);
    }
}

